<?php
declare(strict_types=1);header('Content-Type: application/json; charset=utf-8');require_once __DIR__.'/../../includes/staff/auth.php';require_once __DIR__.'/../../includes/staff/webauthn.php';require_login();try{$p=json_decode(file_get_contents('php://input'),true);$c=$_SESSION['webauthn_reg_challenge']??'';$t=(int)($_SESSION['webauthn_reg_time']??0);unset($_SESSION['webauthn_reg_challenge'],$_SESSION['webauthn_reg_time']);if(!$c||!$t||time()-$t>120)throw new RuntimeException('Registration expired.');$client=b64url_decode($p['response']['clientDataJSON']??'');$attObj=b64url_decode($p['response']['attestationObject']??'');verify_client_data($client,'webauthn.create',$c);[$att,$n]=cbor_decode_at($attObj,0);if(!is_array($att)||!isset($att['authData']))throw new RuntimeException('Invalid attestation data.');$parsed=parse_registration_auth_data($att['authData']);$cred=b64url_encode($parsed['credential_id']);if(!hash_equals($cred,$p['id']??''))throw new RuntimeException('Credential ID mismatch.');$pem=cose_key_to_pem($parsed['cose']);$label=trim($p['label']??'Passkey')?:'Passkey';$trans=$p['response']['transports']??[];$trans=is_array($trans)?implode(',',array_slice($trans,0,10)):'';$st=current_staff();$s=staff_db()->prepare("INSERT INTO staff_passkeys(staff_id,credential_id,public_key_pem,sign_count,label,transports) VALUES(?,?,?,?,?,?)");$s->execute([$st['id'],$cred,$pem,$parsed['sign_count'],mb_substr($label,0,120),mb_substr($trans,0,255)]);log_activity('passkey.register','staff_passkey',(string)staff_db()->lastInsertId(),'Registered passkey.');echo json_encode(['ok'=>true,'message'=>'Passkey registered successfully.']);}catch(Throwable $e){http_response_code(400);echo json_encode(['ok'=>false,'message'=>$e->getMessage()]);}
